        members(json!({ "QueueNames": names }))
    }

    fn delete_queue(&mut self, name: &str) -> Result<Members, Error> {
        self.queues
            .remove(name)
            .ok_or_else(|| no_such_queue(name))?;
        for queue in self.queues.values_mut() {
