    send(&mut s, "q", "poison");
    tick(&mut s, 3);
    receive(&mut s, "q", 1);
    tick(&mut s, 10);
    assert_eq!(receive(&mut s, "q", 1)[0]["ReceiveCount"], 2);
    tick(&mut s, 10);
