    for handle in ["", "garbage", "r-0", "r-2", "r-01", "r-+1", "R-1", "r-1 ", " r-1", "r--1", "r-", "m-1", "r-99999999999999999999999"] {
        assert_eq!(code(&delete(&mut s, "q", handle)), "ReceiptHandleInvalid", "{handle:?}");
        assert_eq!(code(&change(&mut s, "q", handle, 5)), "ReceiptHandleInvalid", "{handle:?}");
    }
    assert_eq!(delete(&mut s, "q", "r-1"), json!({"ok": true}));
}

